import { test } from "node:test";
import assert from "node:assert/strict";
import { buildMap, decodeReplay, simulate, type Sym } from "./frenzy-sim.ts";

// Produced by server/src/game/frenzy.ts: seed 777, fallback prices, 1200 ticks of input.
const FIXTURE = {
  mass: {"SOL": 1, "DOGE": 1, "AVAX": 1, "ETH": 6, "BNB": 4.9, "BTC": 24} as Record<Sym, number>,
  hex: "",
  x: 1178.5509793999868,
  y: 2363.8728738,
  m: 14.556519159538492,
  eaten: 25,
};

test("the browser simulation replays a server minute to the same state, bit for bit", () => {
  const bytes = Uint8Array.from(FIXTURE.hex.match(/../g)!.map((h) => parseInt(h, 16)));
  const rep = decodeReplay(bytes);
  assert.equal(rep.seed, 777);
  const map = buildMap(rep.seed, { mass: FIXTURE.mass });
  const out = simulate(map, rep.entries);
  assert.equal(out.x, FIXTURE.x);
  assert.equal(out.y, FIXTURE.y);
  assert.equal(out.m, FIXTURE.m);
  assert.equal(out.eaten, FIXTURE.eaten);
});
